import{_ as d,a0 as e,w as p,s as r,I as t,x as a,a1 as s,A as i,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"Windows 11 的外观受到了 KDE Plasma 和 GNOME 的启发吗？ | LCTT x X-CMD","titleTemplate":false,"description":"Windows 11 的外观受到了 KDE Plasma 和 GNOME 的启发吗？ | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Windows 11 的外观受到了 KDE Plasma 和 GNOME 的启发吗？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Windows 11 的外观受到了 KDE Plasma 和 GNOME 的启发吗？ | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210626 Windows 11 Look Inspired by KDE Plasma and GNOME","title":"Windows 11 的外观受到了 KDE Plasma 和 GNOME 的启发吗？","tag":"202108","desc":""},"relativePath":"202108/20210626 Windows 11 Look Inspired by KDE Plasma and GNOME.md","filePath":"[post].md"}'),m={name:"202108/20210626 Windows 11 Look Inspired by KDE Plasma and GNOME.md"};function w(u,n,g,E,b,W){const o=e("Link");return p(),r("div",null,[n[21]||(n[21]=t("h1",{id:"windows-11-的外观受到了-kde-plasma-和-gnome-的启发吗",tabindex:"-1"},[a("Windows 11 的外观受到了 KDE Plasma 和 GNOME 的启发吗？ "),t("a",{class:"header-anchor",href:"#windows-11-的外观受到了-kde-plasma-和-gnome-的启发吗","aria-label":"Permalink to “Windows 11 的外观受到了 KDE Plasma 和 GNOME 的启发吗？”"},"​")],-1)),n[22]||(n[22]=t("blockquote",null,[t("p",null,"截图显示，微软即将发布的 Windows 11 操作系统与我们所心爱的 KDE Plasma 和 GNOME 有许多相似之处。它们到底有多相似呢？我们试着比较了一下。")],-1)),n[23]||(n[23]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202108/06/103308cfoo3xoz2c002hx2.jpg",alt:""})],-1)),n[24]||(n[24]=t("p",null,[a("我曾记得一句俗话 —— “"),t("ruby",null,[a("优秀者模仿，伟大者剽窃"),t("rt",null,"Good artists copy. Great artists steal")]),a("”。我不认识 Windows 11 背后的设计团队，但他们似乎很大程度上受到了 Linux 桌面的影响。如果你回顾近几年来的 Windows 系统外观 —— 从 Windows XP 到 7，再到 10 —— 整体视觉上都没有什么太大的变化，直到今天为止。")],-1)),n[25]||(n[25]=t("p",null,"Windows 操作系统的新版本通常有 5 到 7 年的生命周期。如果你试着回想 Windows 提供给你的个性化选项，你会发现这些选项近几年来基本都是一致的，甚至包括开始菜单位置、宽度、颜色在内的桌面整体的体验，一切都没变过。",-1)),t("p",null,[n[1]||(n[1]=a("但随着 Windows 11 的全新外观，这一点终于改变了。让我带你看一些我之前所见过的截图，并且分析一下，它们到底和流行的 Linux ",-1)),s(o,{href:"https://www.debugpoint.com/category/desktop-environment"},{default:i(()=>[...n[0]||(n[0]=[a("桌面环境",-1)])]),_:1}),n[2]||(n[2]=a("（如 KDE Plasma 和 GNOME）有多相似。",-1))]),n[26]||(n[26]=l('<h3 id="windows-11-的外观受到了-kde-plasma-和-gnome-的启发" tabindex="-1">Windows 11 的外观受到了 KDE Plasma 和 GNOME 的启发？ <a class="header-anchor" href="#windows-11-的外观受到了-kde-plasma-和-gnome-的启发" aria-label="Permalink to “Windows 11 的外观受到了 KDE Plasma 和 GNOME 的启发？”">​</a></h3><h4 id="开始菜单和任务栏" tabindex="-1">开始菜单和任务栏 <a class="header-anchor" href="#开始菜单和任务栏" aria-label="Permalink to “开始菜单和任务栏”">​</a></h4><p>传统的开始菜单和任务栏主题在 Windows 11 上有所变化。开始菜单和任务栏图标位于任务栏中央（默认视图）。Windows 也在设置中提供了将任务栏图标和开始菜单移回左侧的选项。</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/06/Windows-11-Start-menu-in-light-mode.jpg" alt="Windows 11 – 浅色模式下的开始菜单"></p><p>整体的布局方式和默认图标的色彩让我想起了 KDE Plasma 的任务栏和启动器。这些图标很精致，并且居中，给你带来一种类似 GNOME 上 Adwaita 图标的观感，而任务栏就更像是 KDE Plasma 的任务栏。</p><p>当你打开开始菜单后，它为你提供不同的图标和选项的排列方式。此外，当你开始打字时，顶部的搜索选项就会弹出。</p><p>现在，来看看全新设计的 KDE Plasma 启动器。我知道间距、图标大小和清晰度并不完全一致，但你可以看到，两者看起来有多么惊人的相似。</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/06/KDE-Plasma-5.22-Launcher-in-Light-mode.jpg" alt="KDE Plasma 5.22 亮色模式下的启动器"></p>',8)),t("p",null,[n[4]||(n[4]=a("如果你正在使用 GNOME 或 Xfce 桌面，借助 ",-1)),s(o,{href:"https://gitlab.com/LinxGem33/Arc-Menu"},{default:i(()=>[...n[3]||(n[3]=[a("Arc Menu",-1)])]),_:1}),n[5]||(n[5]=a(" 和一些小修改，你可以让两者看上去完全一致。",-1))]),n[27]||(n[27]=l('<p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2020/12/gnomecustomize2020-2-1024x576.jpg" alt="修改过的 Arc Menu"></p><h4 id="窗口装饰" tabindex="-1">窗口装饰 <a class="header-anchor" href="#窗口装饰" aria-label="Permalink to “窗口装饰”">​</a></h4><p>按照传统，GNOME 总是用圆角作为标准的窗口装饰。作为对照，Windows 则一直采用直角作为窗口装饰 —— 似乎一直都这样，直到现在为止。嗯，在 Windows 11 中，所有窗口装饰都是圆角，看起来很好。圆角的概念不是什么版权专利或者新想法，这就有一个问题了，为什么现在全都在用圆角？是有什么隐藏的目的吗？</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/06/Rounded-Corners-in-Windows-Explorer-and-Nautilus-1024x716.jpg" alt="Windows 资源管理器和 Nautilus 的圆角"></p><p>哦，还记得 GNOME 的应用程序菜单的小指示器吗？这些小点提示着这里到底有多少页的应用程序。Windows 11 似乎也使用了这种这种思路。</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/06/Dots-in-paging-1024x468.jpg" alt="标记页面数量的小点"></p><h4 id="调色盘" tabindex="-1">调色盘 <a class="header-anchor" href="#调色盘" aria-label="Permalink to “调色盘”">​</a></h4><p>Windows 多年来始终有基于“蓝色”或其他蓝色变体的主题。虽然用户可以自行更改任务栏、开始菜单背景、窗口标题栏颜色，但借助这个选项，调色板与亮暗模式结合，展示出巨大变化，给 Windows 桌面带来了更圆滑、迷人的外观。也许这个灵感源自 Ubuntu、KDE 或者其它风格的调色板。</p><h4 id="暗黑模式" tabindex="-1">暗黑模式 <a class="header-anchor" href="#暗黑模式" aria-label="Permalink to “暗黑模式”">​</a></h4><p>Windows 11 首次官方支持了暗黑模式，或者说是暗色主题。那么，我就直接在下面放两张截图，由大家自己评判。左侧是 Windows 11 暗黑模式下的开始菜单，右侧是使用了 Breeze Dark 主题的 KDE Plasma。</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/06/Comparison-of-Windows-11-Start-Menu-and-KDE-Plasma-1024x505.jpg" alt="Windows 11 开始菜单与 KDE Plasma 的比较"></p><h4 id="全新桌面小组件" tabindex="-1">全新桌面小组件 <a class="header-anchor" href="#全新桌面小组件" aria-label="Permalink to “全新桌面小组件”">​</a></h4><p>灵感的启发从来不会停止。还记得 KDE Plasma 的小组件吗？其实，这也不是什么新概念，然而小组件已经出现在 Windows 11。这是全新小组件面板的截图。你可以添加、移除或者重新排序这些小组件。</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/06/Widgets-menu-1024x833.jpg" alt="小组件菜单"></p><p>这些只是吸引我眼球的冰山一角。也许 Windows 11 还有许多“灵感”来“启发”它的外观。</p><p>但问题来了 —— 为什么现在是一次推出这些功能和外观的最佳时机？</p><h3 id="结束语" tabindex="-1">结束语 <a class="header-anchor" href="#结束语" aria-label="Permalink to “结束语”">​</a></h3><p>实话实说，当我第一次看到 Windows 11 的新外观时，我脑袋里就浮现出 Breeze Dark 主题的 KDE Plasma。借助很少量的修改，你可以让 KDE Plasma 看上去像 Windows 11。这本身就说明了它们两者是有多么地相似。</p><p>如果你看向整个桌面操作系统的市场，竞争者只有 Windows、Linux 桌面和 macOS。至今为止，它们的外观都有明显的标志性特征，例如 macOS 有自己独一无二的外观。直到现在，Windows 也有一样的蓝色主题的常规开始菜单，等等。但借助这些新变化，Windows 为用户提供了更丰富的定制选项，让它看上去更像 Linux 桌面。</p><p>在我个人看来，Windows 团队需要一种不同的标志性特征，而不是一直从我们心爱的 Linux 桌面获得“启发”。</p><p>我不知道未来会发生什么，但现在看来，“E-E-E” 还在竭尽全力运作。（LCTT 译注：“E-E-E”是微软臭名昭著的<ruby>拥抱、扩展再消灭<rt>Embrace, extend, and extinguish</rt></ruby>策略。）</p><p>再会。</p><hr>',23)),t("p",null,[n[7]||(n[7]=a("via: ",-1)),s(o,{href:"https://www.debugpoint.com/2021/06/windows-11-inspiration-linux-kde-plasma/"},{default:i(()=>[...n[6]||(n[6]=[a("https://www.debugpoint.com/2021/06/windows-11-inspiration-linux-kde-plasma/",-1)])]),_:1})]),t("p",null,[n[12]||(n[12]=a("作者：",-1)),s(o,{href:"https://www.debugpoint.com/author/admin1/"},{default:i(()=>[...n[8]||(n[8]=[a("Arindam",-1)])]),_:1}),n[13]||(n[13]=a(" 选题：",-1)),s(o,{href:"https://github.com/lujun9972"},{default:i(()=>[...n[9]||(n[9]=[a("lujun9972",-1)])]),_:1}),n[14]||(n[14]=a(" 译者：",-1)),s(o,{href:"https://github.com/imgradeone"},{default:i(()=>[...n[10]||(n[10]=[a("imgradeone",-1)])]),_:1}),n[15]||(n[15]=a(" 校对：",-1)),s(o,{href:"https://github.com/wxy"},{default:i(()=>[...n[11]||(n[11]=[a("wxy",-1)])]),_:1})]),t("p",null,[n[18]||(n[18]=a("本文由 ",-1)),s(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...n[16]||(n[16]=[a("LCTT",-1)])]),_:1}),n[19]||(n[19]=a(" 原创编译，",-1)),s(o,{href:"https://linux.cn/"},{default:i(()=>[...n[17]||(n[17]=[a("Linux中国",-1)])]),_:1}),n[20]||(n[20]=a(" 荣誉推出",-1))])])}const D=d(m,[["render",w]]);export{f as __pageData,D as default};
